messages.content:
Tool response:
Tool: create_application_round
Description: Create a new application round for a specified program with given dates, fee, and submission limit.
The round is associated with a specific academic year and semester.
Parameters:
    {
      "type": "object",
      "properties": {
        "program_name": {
          "type": "string",
          "title": "Program Name",
          "description": "Name of the program (e.g., 'Master of Data Science')"
        },
        "academic_year": {
          "type": "integer",
          "title": "Academic Year",
          "description": "Academic year for the application round (e.g., 2026)"
        },
        "semester": {
          "type": "string",
          "title": "Semester",
          "description": "Semester of the application round (e.g., 'Fall')"
        },
        "start_date": {
          "type": "string",
          "title": "Start Date",
          "description": "Start date of the application period in YYYY-MM-DD format"
        },
        "end_date": {
          "type": "string",
          "title": "End Date",
          "description": "End date of the application period in YYYY-MM-DD format"
        },
        "application_fee": {
          "type": "number",
          "title": "Application Fee",
          "description": "Application fee amount in USD"
        },
        "submission_limit": {
          "type": "integer",
          "title": "Submission Limit",
          "description": "Maximum number of applications allowed per applicant"
        }
      },
      "required": [
        "program_name",
        "academic_year",
        "semester",
        "start_date",
        "end_date",
        "application_fee",
        "submission_limit"
      ]
    }
